/* Thread 3 hero sprite - archetype: INTERFACE, 48 frames, 5x10 grid, native ratio 16:9 */
.hero-sprite {
  aspect-ratio: 16 / 9;
  width: min(90vw, 1200px);
  height: auto;
  margin: 0 auto;
  background-image: url('sprite.webp');
  background-repeat: no-repeat;
  background-size: 500% 1000%; /* percentage, not px - required, see this project's own bleed-bug finding */
  background-position: 50% 100%; /* unconditional base state: the actual last frame's grid cell (2,9) - NOT always "100% 100%", since frameCount doesn't always fill the grid exactly */
}

@supports (animation-timeline: scroll()) {
  .hero-sprite {
    animation: hero-scrub-interface linear both;
    animation-timeline: scroll(root block);
  }
}

@keyframes hero-scrub-interface {
